package cn.balltv.portal;
import java.io.*;import java.security.*;import java.security.cert.*;import java.util.*;import javax.net.ssl.*;
/** Platform validation first, then a small documented set of public CA roots. */
public final class CompatTrust implements X509TrustManager {
 final X509TrustManager system,extra;
 CompatTrust(X509TrustManager system,X509TrustManager extra){this.system=system;this.extra=extra;}
 static X509TrustManager manager(KeyStore store)throws GeneralSecurityException{TrustManagerFactory f=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());f.init(store);for(TrustManager m:f.getTrustManagers())if(m instanceof X509TrustManager)return (X509TrustManager)m;throw new KeyStoreException("No X509 trust manager");}
 public static CompatTrust load(InputStream pem)throws Exception{KeyStore store=KeyStore.getInstance(KeyStore.getDefaultType());store.load(null,null);ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] chunk=new byte[4096];int n;while((n=pem.read(chunk))!=-1){if(bytes.size()+n>65536)throw new CertificateException("Root bundle too large");bytes.write(chunk,0,n);}ArrayList<java.security.cert.Certificate> roots=new ArrayList<java.security.cert.Certificate>();java.util.regex.Matcher blocks=java.util.regex.Pattern.compile("-----BEGIN CERTIFICATE-----[\\s\\S]+?-----END CERTIFICATE-----").matcher(bytes.toString("US-ASCII"));CertificateFactory factory=CertificateFactory.getInstance("X.509");while(blocks.find())roots.add(factory.generateCertificate(new ByteArrayInputStream(blocks.group().getBytes("US-ASCII"))));if(roots.size()!=6)throw new CertificateException("Unexpected compatibility roots");int i=0;for(java.security.cert.Certificate c:roots){X509Certificate root=(X509Certificate)c;if(root.getBasicConstraints()<0||!root.getSubjectX500Principal().equals(root.getIssuerX500Principal()))throw new CertificateException("Not a CA root");root.verify(root.getPublicKey());store.setCertificateEntry("compat-"+(i++),root);}return new CompatTrust(manager(null),manager(store));}
 public void checkServerTrusted(X509Certificate[] chain,String auth)throws CertificateException{if(chain==null||chain.length==0)throw new CertificateException("Empty certificate chain");chain[0].checkValidity();try{system.checkServerTrusted(chain,auth);}catch(CertificateException first){try{extra.checkServerTrusted(chain,auth);}catch(CertificateException second){throw new CertificateException("Certificate chain is not trusted",first);}}}
 public void checkClientTrusted(X509Certificate[] chain,String auth)throws CertificateException{system.checkClientTrusted(chain,auth);}
 public X509Certificate[] getAcceptedIssuers(){X509Certificate[] a=system.getAcceptedIssuers(),b=extra.getAcceptedIssuers(),all=new X509Certificate[a.length+b.length];System.arraycopy(a,0,all,0,a.length);System.arraycopy(b,0,all,a.length,b.length);return all;}
}
